import{_ as i,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"给初学者的 type 命令教程 | LCTT x X-CMD","titleTemplate":false,"description":"给初学者的 type 命令教程 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"给初学者的 type 命令教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"给初学者的 type 命令教程 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180313 The Type Command Tutorial With Examples For Beginners","title":"给初学者的 type 命令教程","tag":"201804","desc":""},"relativePath":"201804/20180313 The Type Command Tutorial With Examples For Beginners.md","filePath":"[post].md"}'),c={name:"201804/20180313 The Type Command Tutorial With Examples For Beginners.md"};function h(g,s,u,m,k,y){const e=l("Link");return o(),d("div",null,[s[13]||(s[13]=r(`<h1 id="给初学者的-type-命令教程" tabindex="-1">给初学者的 type 命令教程 <a class="header-anchor" href="#给初学者的-type-命令教程" aria-label="Permalink to “给初学者的 type 命令教程”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/Type-command-720x340.png" alt=""></p><p><code>type</code> 命令用于查找 Linux 命令的信息。顾名思义，你可以使用 <code>type</code> 命令轻松找出给定的命令是否是别名、shell 内置命令、文件、函数或关键字。另外，你也可以找到命令的实际路径。为什么有人需要找到命令类型？例如，如果你经常在共享的计算机上工作，则某些人可能会故意或意外地为特定的 Linux 命令创建别名来执行不需要的操作，例如 <code>alias ls = rm -rf /</code>。因此，在发生更糟糕的事情之前检查它们总是一个好主意。这是 <code>type</code> 命令有用的地方。</p><p>让我给你看一些例子。</p><p>不带任何选项运行 <code>type</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type ls</span></span>
<span class="line"><span>ls is aliased to \`ls --color=auto&#39;</span></span></code></pre></div><p>正如你在上面的输出中看到的那样，<code>ls</code> 命令已被别名为 <code>ls -color-auto</code>。但是，它是无害的。但只要想想 <code>ls</code> 如果被别名为了其他一些危险的命令。你不想那样，是吗？</p><p>你可以使用 <code>-t</code> 选项仅找出 Linux 命令的类型。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type -t ls</span></span>
<span class="line"><span>alias</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t mkdir</span></span>
<span class="line"><span>file</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t pwd</span></span>
<span class="line"><span>builtin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t if</span></span>
<span class="line"><span>keyword</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ type -t rvm</span></span>
<span class="line"><span>function</span></span></code></pre></div><p>该命令仅显示命令的类型，例如别名。它不显示被别名的内容。如果该命令找不到，你将在终端中看不到任何内容。</p><p><code>type</code> 命令的另一个有用的地方是我们可以很容易地找出给定 Linux 命令的绝对路径。为此，请使用 <code>-p</code> 选项，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type -p cal</span></span>
<span class="line"><span>/usr/bin/cal</span></span></code></pre></div><p>这与 <code>which ls</code> 命令类似。如果给定的命令是别名，则不会打印任何内容。</p><p>要显示命令的所有信息，请使用 <code>-a</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ type -a ls</span></span>
<span class="line"><span>ls is aliased to \`ls --color=auto&#39;</span></span>
<span class="line"><span>ls is /usr/bin/ls</span></span>
<span class="line"><span>ls is /bin/ls</span></span></code></pre></div><p>如你所见，<code>-a</code> 标志显示给定命令的类型及其绝对路径。有关更多详细信息，请参阅手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man type</span></span></code></pre></div><p>希望这有帮助。会有更多的好东西。请继续访问！</p><p>干杯!</p><hr>`,20)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.ostechnix.com/the-type-command-tutorial-with-examples-for-beginners/"},{default:t(()=>[...s[0]||(s[0]=[a("https://www.ostechnix.com/the-type-command-tutorial-with-examples-for-beginners/",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=a("作者：",-1)),n(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[a("SK",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[3]||(s[3]=[a("geekpi",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const x=i(c,[["render",h]]);export{T as __pageData,x as default};
